'''Small public-format documents generated by the verifier for GUI episodes.'''
import xml.etree.ElementTree as ET


DESCRIPTIONS = {
    'beat.h2song': 'Hydrogen song with one sampled instrument and three notes at different positions and levels',
    'duet.mmp': 'LMMS project at 120 BPM with two named instrument tracks, Low and High, each holding different notes',
}


def build(ctx, name):
    if name == 'beat.h2song':
        sample, _ = ctx.sample('tone-440')
        song = ET.Element('song')

        def text(parent, key, value):
            ET.SubElement(parent, key).text = str(value)

        for key, value in [('version', '0.9.6'), ('name', 'Three beats'), ('author', 'Fixture'), ('bpm', 120), ('mode', 'song')]:
            text(song, key, value)
        inst = ET.SubElement(ET.SubElement(song, 'instrumentList'), 'instrument')
        for key, value in [('id', 0), ('name', 'Tone'), ('volume', .8), ('pan_L', .5), ('pan_R', .5)]:
            text(inst, key, value)
        layer = ET.SubElement(inst, 'layer')
        text(layer, 'filename', sample)
        pattern = ET.SubElement(ET.SubElement(song, 'patternList'), 'pattern')
        text(pattern, 'name', 'Three beats')
        text(pattern, 'size', 192)
        notes = ET.SubElement(pattern, 'noteList')
        for pos, velocity, key in [(0, .9, 'C0'), (48, .6, 'E0'), (132, .75, 'G0')]:
            node = ET.SubElement(notes, 'note')
            for field, value in [('position', pos), ('velocity', velocity), ('pan_L', .5), ('pan_R', .5),
                                 ('key', key), ('note_off', 'false'), ('instrument', 0)]:
                text(node, field, value)
        group = ET.SubElement(ET.SubElement(song, 'patternSequence'), 'group')
        text(group, 'patternID', 'Three beats')
        return ET.tostring(song, encoding='utf-8', xml_declaration=True)
    if name == 'duet.mmp':
        import projectxml as px
        project = px.Project(bpm=120)
        project.add(px.instrument_track('Low', 'tripleoscillator', notes=[(0, 48, 48), (96, 48, 52)], vol=45))
        project.add(px.instrument_track('High', 'tripleoscillator', notes=[(48, 24, 72), (144, 36, 76)], vol=30))
        return project.xml().encode()
    raise ValueError('unknown generated document ' + name)
